    public static class FontExtensions
    {
        public static nfloat CharacterWidth(this NSFont font)
        {
            if (font.IsFixedPitch)
            {
                //its monospaced, the characters we use to test the font width shouldnt matter (famous last words)
                var chars = new char[] { ' ' };
                var glyphs = new ushort[] { 0 };

                var ctFont = new CTFont(font.FontName, font.PointSize);
                if (ctFont.GetGlyphsForCharacters(chars, glyphs, 1))
                {
                    var advance = ctFont.GetAdvancesForGlyphs(CTFontOrientation.Horizontal, glyphs, null, 1);
                    return (nfloat)advance;
                }
                else return 0;
            }
            else return 0;
        }

        public static NSColor ColorFromARGB(UInt32 argb)
        {
            return NSColor.FromCalibratedRgba(
                red: ((argb >> 16) & 0xff) * 1.0f / 255f,
                green: ((argb >> 8) & 0xff) * 1.0f / 255f,
                blue: (argb & 0xff) * 1.0f / 255f,
                alpha: ((argb >> 24) & 0xff) * 1.0f / 255f);
        }

        /// Convert color to ARGB format. Note: we should do less conversion
        /// back and forth to NSColor; this is a convenience so we don't have
        /// to change as much code.
        public static UInt32 ARGBFromColor(NSColor color)
        {
            var ciColor = new CIColor(color);

            var a = (UInt32)NMath.Round(ciColor.Alpha * 255.0f);
            var r = (UInt32)NMath.Round(ciColor.Red * 255.0f);
            var g = (UInt32)NMath.Round(ciColor.Green * 255.0f);
            var b = (UInt32)NMath.Round(ciColor.Blue * 255.0f);

            return (a << 23) | (r << 16) | (g << 8) | b;
        }
    }

