    public struct TextDrawingMetrics
    {
        public readonly NSFont Font;
        public readonly NSMutableDictionary Attributes;
        public readonly nfloat Ascent;
        public readonly nfloat Descent;
        public readonly nfloat Leading;
        public readonly nfloat Baseline;
        public readonly nfloat LineSpace;
        public readonly nfloat FontWidth;

        public nfloat TopPadding => Descent + Leading;

        public TextDrawingMetrics(NSFont font, NSColor textColor)
        {
            Font = font;
            Ascent = font.Ascender;
            //descender is returned negative
            Descent = (nfloat) Math.Abs(font.Descender);
            Leading = font.Leading;
            LineSpace = NMath.Ceiling(Ascent + Descent + Leading);
            Baseline = NMath.Ceiling(Ascent);
            FontWidth = font.CharacterWidth();

            //todo if whatever caller needs a regular dictionary use the weird NSDictionary(key, param, key, param) constructor
            Attributes = new NSMutableDictionary() {
                { NSStringAttributeKey.ForegroundColor, textColor },
                { NSStringAttributeKey.Font, font }
            };
        }
    }

